        const lo = hi - 7;
        for (let k = 0; k < G * G; k++) { const t = Math.max(0, Math.min(1, (dg.l[k] - lo) / (hi - lo))), u = Math.pow(t, 1.6); im.data[4 * k] = 6 + u * (col[0] - 6); im.data[4 * k + 1] = 8 + u * (col[1] - 8); im.data[4 * k + 2] = 11 + u * (col[2] - 11); im.data[4 * k + 3] = 255; }
