                const x0 = X(A.P[2 * i]), y0 = Y(A.P[2 * i + 1]);
                let dx = A.V[2 * i] * sc, dy = -A.V[2 * i + 1] * sc, L = Math.hypot(dx, dy); if (L < 0.5) continue;
                if (L > maxL) { dx *= maxL / L; dy *= maxL / L; L = maxL; }
