const P11CPP = {
    data: `
        // ── 数据：三臂螺旋 = 48 个各向同性高斯分量的等权混合（每条臂 16 个，σ = 0.1）。我们知道它的密度，模型不知道 ──
        struct Spiral { std::vector<float> mu; std::vector<int> arm; float sigma = 0.1f; int M = 0; };

        // 第 c 条臂上参数 u ∈ [0, 1] 处的点：半径 0.22 → 1，同时转过 180°
        void armPoint(int c, double u, double& x, double& y) {
            const double PI = 3.141592653589793;
            double r = 0.22 + 0.78 * u, a = 2 * PI * c / 3 + 0.35 + PI * u;
            x = r * std::cos(a);
            y = r * std::sin(a);
        }

        Spiral makeSpiral() {
            Spiral g;
            const int NS = 2000;
            for (int c = 0; c < 3; c++) {
                std::vector<float> cum = floats(NS + 1);              // 弧长表：先细分，再沿弧长等间距放分量 → 每条臂上密度均匀
                double px = 0, py = 0;
                armPoint(c, 0, px, py);
                for (int i = 1; i <= NS; i++) {
                    double x = 0, y = 0;
                    armPoint(c, (double)i / NS, x, y);
                    cum[i] = cum[i - 1] + (float)std::hypot(x - px, y - py);
                    px = x; py = y;
                }
                int n = (int)std::lround(cum[NS] / 0.14) + 1;         // 每 0.14 弧长一个分量 → 16 个
                int j = 0;
                for (int k = 0; k < n; k++) {
                    float s = cum[NS] * k / (n - 1);
                    while (j < NS - 1 && cum[j + 1] < s) j++;
                    double f = (s - cum[j]) / std::max(1e-12f, cum[j + 1] - cum[j]), x = 0, y = 0;
                    armPoint(c, (j + f) / NS, x, y);
                    g.mu.push_back((float)x); g.mu.push_back((float)y); g.arm.push_back(c);
                }
            }
            g.M = (int)g.arm.size();
            return g;
        }

        // 采样：随机挑一个分量 k，再加 N(0, σ²I)。arm[i] = 第 i 个点所属的臂（Step 07 的类别标签）
        Tensor sampleSpiral(const Spiral& g, int n, Rng& r, std::vector<int>& arm) {
            Tensor X = zeros(n, 2);
            arm = ints(n);
            for (int i = 0; i < n; i++) {
                int k = randint(r, g.M);
                X.at(i, 0) = g.mu[2 * k] + g.sigma * randn(r);
                X.at(i, 1) = g.mu[2 * k + 1] + g.sigma * randn(r);
                arm[i] = g.arm[k];
            }
            return X;
        }

        // 多尺度 RBF 核 k(x, y) = Σ_h exp(−|x − y|²/(2h²))，h = 0.05 / 0.15 / 0.45（臂的粗细 / 臂间距 / 整体形状）
        double rbf(double d2) {
            return std::exp(-d2 / (2 * 0.05 * 0.05)) + std::exp(-d2 / (2 * 0.15 * 0.15)) + std::exp(-d2 / (2 * 0.45 * 0.45));
        }

        // 生成样本 X 与真实分布之间的 MMD²（×1000，对 X 无偏）。真实分布是高斯混合，核均值嵌入有解析式：
        //   E_y k_h(x, y) = (1/M)·Σ_k h²/(h² + σ²)·exp(−|x − μ_k|²/(2(h² + σ²)))，所以不需要参考样本
        double mmdToSpiral(const Tensor& X, const Spiral& g) {
            const double H[3] = {0.05, 0.15, 0.45};
            int n = X.rows;
            double sxx = 0, sxy = 0, syy = 0;
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++) { double dx = X.at(i, 0) - X.at(j, 0), dy = X.at(i, 1) - X.at(j, 1); sxx += rbf(dx * dx + dy * dy); }
            sxx = 2 * sxx / ((double)n * (n - 1));
            for (double h : H) {
                double v1 = h * h + g.sigma * g.sigma, v2 = h * h + 2 * g.sigma * g.sigma;
                for (int i = 0; i < n; i++)
                    for (int k = 0; k < g.M; k++) { double dx = X.at(i, 0) - g.mu[2 * k], dy = X.at(i, 1) - g.mu[2 * k + 1]; sxy += h * h / v1 * std::exp(-(dx * dx + dy * dy) / (2 * v1)) / ((double)n * g.M); }
                for (int a = 0; a < g.M; a++)
                    for (int b = 0; b < g.M; b++) { double dx = g.mu[2 * a] - g.mu[2 * b], dy = g.mu[2 * a + 1] - g.mu[2 * b + 1]; syy += h * h / v2 * std::exp(-(dx * dx + dy * dy) / (2 * v2)) / ((double)g.M * g.M); }
            }
            return 1000 * (sxx + syy - 2 * sxy);
        }`,
    sched: `
        // ── 噪声日程。下标 t = 0…T（T = 1000），abar[0] = 1：t = 0 是干净数据 ──
        const int T_STEPS = 1000;
        struct Schedule { std::vector<float> beta, abar; };

        // cosine 日程的 f(u)（Nichol & Dhariwal 2021，s = 0.008）：ᾱ_t = f(t/T)/f(0)
        double cosineF(double u) { double c = std::cos((u + 0.008) / 1.008 * 3.141592653589793 / 2); return c * c; }

        Schedule makeSchedule(bool cosine) {
            Schedule s;
            s.beta = floats(T_STEPS + 1);
            s.abar = floats(T_STEPS + 1, 1.f);
            double ab = 1;
            for (int t = 1; t <= T_STEPS; t++) {
                double b = cosine ? std::min(0.999, 1 - cosineF((double)t / T_STEPS) / cosineF((double)(t - 1) / T_STEPS))   // β_t = 1 − ᾱ_t/ᾱ_{t−1}，截断在 0.999
                                  : 1e-4 + (0.02 - 1e-4) * (t - 1) / (T_STEPS - 1);                                            // Ho et al. 2020：1e-4 → 0.02 线性
                ab *= 1 - b;                                              // ᾱ_t = Π_{s≤t} (1 − β_s)
                s.beta[t] = (float)b;
                s.abar[t] = (float)ab;
            }
            return s;
        }

        // 前向加噪，一步到位（不用真的迭代 t 次）：x_t = √ᾱ_t·x₀ + √(1 − ᾱ_t)·ε，ε ~ N(0, I)
        Tensor qSample(const Tensor& x0, const Schedule& s, int t, const Tensor& eps) {
            Tensor xt = zeros(x0.rows, x0.cols);
            float a = std::sqrt(s.abar[t]), sg = std::sqrt(1 - s.abar[t]);
            for (int i = 0; i < xt.size(); i++) xt.v[i] = a * x0.v[i] + sg * eps.v[i];
            return xt;
        }

        // 逐步加噪的马尔可夫链（定义）：x_t = √(1 − β_t)·x_{t−1} + √β_t·z。连乘 t 次后正好是上面的 q(x_t | x₀)
        void forwardStep(Tensor& x, const Schedule& s, int t, Rng& r) {
            float c = std::sqrt(1 - s.beta[t]), d = std::sqrt(s.beta[t]);
            for (float& v : x.v) v = c * v + d * randn(r);
        }

        // 信噪比 SNR(t) = ᾱ_t/(1 − ᾱ_t)：信号能量 / 噪声能量
        double logSNR(const Schedule& s, int t) { return std::log(s.abar[t] / (1.0 - s.abar[t])); }`,
    net: `
        // ── 去噪网络 ε_θ(x_t, t)：小 MLP，每层的输入都是 [h, 条件]；条件 = 正弦时间编码（16 维）[+ 类别 one-hot] ──
        const int NF = 8, FF = 4;

        // 正弦时间编码（DDPM 的 get_timestep_embedding）：t ∈ [0, 1000] → [sin(t·ω_k), cos(t·ω_k)]，ω_k = 10000^(−k/7)
        std::vector<float> timestepEmbedding(float t) {
            std::vector<float> e = floats(2 * NF);
            for (int k = 0; k < NF; k++) {
                double w = std::exp(-std::log(10000.0) * k / (NF - 1));
                e[k] = (float)std::sin(t * w);
                e[NF + k] = (float)std::cos(t * w);
            }
            return e;
        }

        // 输入的 Fourier 特征 [x, sin(2^k·π·x), cos(2^k·π·x)]（k = 0…3）：MLP 天生偏爱平滑函数，加上它才学得动臂附近陡峭的 ε
        Tensor fourierFeatures(const Tensor& x) {
            int d = x.cols, f = d * (1 + 2 * FF);
            Tensor out = zeros(x.rows, f);
            for (int i = 0; i < x.rows; i++)
                for (int j = 0; j < d; j++) {
                    out.at(i, j) = x.at(i, j);
                    for (int k = 0; k < FF; k++) {
                        double w = 3.141592653589793 * (1 << k) * x.at(i, j);
                        out.at(i, d + 2 * (j * FF + k)) = (float)std::sin(w);
                        out.at(i, d + 2 * (j * FF + k) + 1) = (float)std::cos(w);
                    }
                }
            return out;
        }

        // nn.Linear 的默认初始化：W、b ~ U(−1/√fan_in, 1/√fan_in)
        Tensor uniformInit(int rows, int cols, float lim, Rng& r) {
            Tensor t = zeros(rows, cols);
            for (float& v : t.v) v = (float)((2 * uniform(r) - 1) * lim);
            return t;
        }

        Linear makeLinearU(int in, int out, Rng& r) {
            float lim = 1 / std::sqrt((float)in);
            Linear l;
            l.W = param(uniformInit(in, out, lim, r));
            l.b = param(uniformInit(1, out, lim, r));
            return l;
        }

        struct Denoiser { std::vector<Linear> layers; Linear out; int din = 2, nCls = 0; bool fourier = true; };

        int condDim(const Denoiser& net) { return 2 * NF + (net.nCls > 0 ? net.nCls + 1 : 0); }

        // 本页：din = 2、width = 48、depth = 3（约 8000 个参数）。nCls > 0：类别条件（one-hot 多一维 = 空条件 ∅，Step 07）
        Denoiser makeDenoiser(int din, int width, int depth, int nCls, bool fourier, Rng& r) {
            Denoiser net;
            net.din = din; net.nCls = nCls; net.fourier = fourier;
            int fin = fourier ? din * (1 + 2 * FF) : din, dc = condDim(net);
            for (int l = 0; l < depth; l++) { net.layers.push_back(makeLinearU(fin + dc, width, r)); fin = width; }
            net.out = makeLinearU(width, din, r);
            return net;
        }

        // 条件矩阵 [n × dc]：第 i 行 = [timestepEmbedding(t_i) | one-hot(c_i)]；c = −1 表示空条件 ∅
        Tensor condRows(const Denoiser& net, const std::vector<float>& t, const std::vector<int>& cls) {
            int n = (int)t.size(), dc = condDim(net);
            Tensor C = zeros(n, dc);
            for (int i = 0; i < n; i++) {
                std::vector<float> e = timestepEmbedding(t[i]);
                for (int k = 0; k < 2 * NF; k++) C.at(i, k) = e[k];
                if (net.nCls > 0) C.at(i, 2 * NF + (cls[i] < 0 ? net.nCls : cls[i])) = 1;
            }
            return C;
        }

        // 前向：h ← SiLU(Linear([h, cond]))，最后一层线性输出 ε̂（流匹配时同一个结构输出速度 v̂）
        Var denoise(const Denoiser& net, const Tensor& x, const Tensor& cond) {
            Var C = constant(cond);
            Var h = constant(net.fourier ? fourierFeatures(x) : x);
            for (const Linear& l : net.layers) h = silu(forward(l, concatCols(h, C)));
            return forward(net.out, h);
        }

        std::vector<Var> parameters(const Denoiser& net) {
            std::vector<Var> ps;
            for (const Linear& l : net.layers) { ps.push_back(l.W); ps.push_back(l.b); }
            ps.push_back(net.out.W); ps.push_back(net.out.b);
            return ps;
        }

        // 深拷贝（EMA 权重要有自己的一份存储；直接复制结构体只会复制指针）
        Denoiser cloneDenoiser(const Denoiser& net) {
            Denoiser c = net;
            for (Linear& l : c.layers) { l.W = param(l.W->val); l.b = param(l.b->val); }
            c.out.W = param(c.out.W->val); c.out.b = param(c.out.b->val);
            return c;
        }`,
    train: `
        // 一步训练（Ho et al. 2020 的 L_simple）：t ~ U{1…T}、ε ~ N(0, I) → x_t = √ᾱ_t·x₀ + √(1−ᾱ_t)·ε → mean‖ε − ε_θ(x_t, t)‖²
        float trainStepEps(Denoiser& net, AdamW& opt, const Tensor& data, const Schedule& s, int B, float lr, Rng& r) {
            Tensor x = zeros(B, 2), eps = zeros(B, 2);
            std::vector<float> t = floats(B);
            for (int b = 0; b < B; b++) {
                int j = randint(r, data.rows), ti = 1 + randint(r, T_STEPS);
                float a = std::sqrt(s.abar[ti]), sg = std::sqrt(1 - s.abar[ti]);
                for (int d = 0; d < 2; d++) { eps.at(b, d) = randn(r); x.at(b, d) = a * data.at(j, d) + sg * eps.at(b, d); }
                t[b] = (float)ti;
            }
            std::vector<Var> ps = parameters(net);
            zeroGrad(ps);
            Var loss = mse(denoise(net, x, condRows(net, t, ints(B, -1))), constant(eps));
            backward(loss);
            clipGradNorm(ps, 1.0f);
            adamwStep(opt, lr);
            return loss->val.v[0];
        }

        // 权重的指数滑动平均（采样用 EMA 权重，比最后一步的权重稳）：θ_ema ← d·θ_ema + (1 − d)·θ，d 从小涨到 decay
        void emaUpdate(Denoiser& ema, const Denoiser& net, int step, float decay) {
            float d = std::min(decay, (1.0f + step) / (10.0f + step));
            std::vector<Var> pe = parameters(ema), pn = parameters(net);
            for (size_t k = 0; k < pe.size(); k++)
                for (int i = 0; i < pe[k]->val.size(); i++) pe[k]->val.v[i] = d * pe[k]->val.v[i] + (1 - d) * pn[k]->val.v[i];
        }

        // 训练循环：Adam（β₂ = 0.999，无权重衰减）、梯度裁剪 1.0、warmup 100 步 + cosine 衰减到 5%；页面里每帧调用一次 trainStepEps
        Denoiser trainDenoiser(const Tensor& data, const Schedule& s, int steps, float maxLR, uint32_t seed) {
            Rng r = makeRng(seed);
            Denoiser net = makeDenoiser(2, 48, 3, 0, true, r), ema = cloneDenoiser(net);
            std::vector<Var> ps = parameters(net);
            AdamW opt = makeAdamW(ps, std::vector<bool>(ps.size(), false), maxLR, 0.f, 0.9f, 0.999f);
            for (int it = 0; it < steps; it++) {
                trainStepEps(net, opt, data, s, 128, cosineLR(it, maxLR, 0.05f * maxLR, 100, steps), r);
                emaUpdate(ema, net, it + 1, 0.995f);
            }
            return ema;
        }`,
    score: `
        // 不求梯度的推理：n 个点共用同一个时刻 t 和类别 c（c = −1：无条件 / 空条件 ∅）
        Tensor predictEps(const Denoiser& net, const Tensor& x, float t, int cls) {
            NoGrad ng;
            return denoise(net, x, condRows(net, floats(x.rows, t), ints(x.rows, cls)))->val;
        }

        // ε̂ 就是换了单位的 score：∇log q_t(x) ≈ −ε̂/√(1 − ᾱ_t)
        Tensor scoreFromEps(const Tensor& eps, const Schedule& s, int t) {
            Tensor sc = zeros(eps.rows, eps.cols);
            float sg = std::sqrt(1 - s.abar[t]);
            for (int i = 0; i < sc.size(); i++) sc.v[i] = -eps.v[i] / sg;
            return sc;
        }

        // Tweedie 公式：E[x₀ | x_t] = (x_t + (1 − ᾱ_t)·∇log q_t)/√ᾱ_t = (x_t − √(1 − ᾱ_t)·ε̂)/√ᾱ_t
        Tensor tweedieX0(const Tensor& x, const Tensor& eps, const Schedule& s, int t) {
            Tensor x0 = zeros(x.rows, x.cols);
            float a = std::sqrt(s.abar[t]), sg = std::sqrt(1 - s.abar[t]);
            for (int i = 0; i < x0.size(); i++) x0.v[i] = (x.v[i] - sg * eps.v[i]) / a;
            return x0;
        }

        // 解析 score（只有知道真实分布才算得出来）：q_t = (1/M)·Σ_k N(√ᾱ·μ_k, v·I)，v = ᾱσ² + 1 − ᾱ
        //   ∇log q_t(x) = (√ᾱ·Σ_k r_k·μ_k − x)/v，r_k ∝ exp(−|x − √ᾱ·μ_k|²/(2v)) 是分量 k 的后验「责任」
        Tensor exactScore(const Spiral& g, const Tensor& x, float abar) {
            Tensor sc = zeros(x.rows, 2);
            float a = std::sqrt(abar), v = abar * g.sigma * g.sigma + (1 - abar);
            std::vector<float> lg = floats(g.M);
            for (int i = 0; i < x.rows; i++) {
                float m = -1e30f;
                for (int k = 0; k < g.M; k++) {
                    float dx = x.at(i, 0) - a * g.mu[2 * k], dy = x.at(i, 1) - a * g.mu[2 * k + 1];
                    lg[k] = -(dx * dx + dy * dy) / (2 * v);
                    m = std::max(m, lg[k]);
                }
                double z = 0, mx = 0, my = 0;
                for (int k = 0; k < g.M; k++) { double e = std::exp(lg[k] - m); z += e; mx += e * g.mu[2 * k]; my += e * g.mu[2 * k + 1]; }
                sc.at(i, 0) = (float)((a * mx / z - x.at(i, 0)) / v);
                sc.at(i, 1) = (float)((a * my / z - x.at(i, 1)) / v);
            }
            return sc;
        }`,
    ddpm: `
        // K 个等间隔时间步：τ_k = round(k·T/K)，τ_K = T（从纯噪声出发）、τ_0 = 0
        int tauAt(int k, int K) { return (int)std::lround((double)k * T_STEPS / K); }

        // x̂₀ 截断到数据范围（同 diffusers 的 clip_sample）：cosine 日程 √ᾱ_T ≈ 5×10⁻⁵，第一步的 (x − σε̂)/√ᾱ 会把网络误差放大上万倍
        float clampX0(float v, float lim) { return std::max(-lim, std::min(lim, v)); }

        // DDPM 祖先采样的一步（Ho et al. 2020 Algorithm 2，可跳步）：x_{t'} ~ q(x_{t'} | x_t, x̂₀) = N(μ̃, β̃·I)
        //   β̃ = (1 − ᾱ_{t'})/(1 − ᾱ_t)·(1 − ᾱ_t/ᾱ_{t'})；μ̃ 写成 √ᾱ_{t'}·x̂₀ + √(1 − ᾱ_{t'} − β̃)·ε̂（与教科书里的 μ̃ 代数上相同）
        void ddpmStep(const Schedule& s, Tensor& x, const Tensor& eps, int t, int tp, Rng& r) {
            float at = s.abar[t], ap = s.abar[tp];
            float var = (1 - ap) / (1 - at) * (1 - at / ap);
            for (int i = 0; i < x.size(); i++) {
                float x0 = clampX0((x.v[i] - std::sqrt(1 - at) * eps.v[i]) / std::sqrt(at), 1.25f);
                x.v[i] = std::sqrt(ap) * x0 + std::sqrt(std::max(0.f, 1 - ap - var)) * eps.v[i] + std::sqrt(var) * randn(r);
            }
        }

        Tensor sampleDDPM(const Denoiser& net, const Schedule& s, int n, int K, Rng& r) {
            Tensor x = randn(n, 2, 1.f, r);                            // x_T ~ N(0, I)
            for (int k = K; k >= 1; k--) {
                int t = tauAt(k, K), tp = tauAt(k - 1, K);
                ddpmStep(s, x, predictEps(net, x, (float)t, -1), t, tp, r);
            }
            return x;
        }`,
    ddim: `
        // DDIM-η 的一步（Song et al. 2021，式 12）：σ = η·√((1−ᾱ_{t'})/(1−ᾱ_t))·√(1 − ᾱ_t/ᾱ_{t'})
        //   x_{t'} = √ᾱ_{t'}·x̂₀ + √(1 − ᾱ_{t'} − σ²)·ε̂ + σ·z。η = 0：确定性；η = 1：与 ddpmStep 相同
        void ddimStep(const Schedule& s, Tensor& x, const Tensor& eps, int t, int tp, float eta, float clip, Rng& r) {
            float at = s.abar[t], ap = s.abar[tp];
            float sig = eta * std::sqrt((1 - ap) / (1 - at) * (1 - at / ap));
            for (int i = 0; i < x.size(); i++) {
                float x0 = clampX0((x.v[i] - std::sqrt(1 - at) * eps.v[i]) / std::sqrt(at), clip);
                x.v[i] = std::sqrt(ap) * x0 + std::sqrt(std::max(0.f, 1 - ap - sig * sig)) * eps.v[i] + (sig > 0 ? sig * randn(r) : 0.f);
            }
        }

        Tensor sampleDDIM(const Denoiser& net, const Schedule& s, Tensor x, int K, float eta, Rng& r) {
            for (int k = K; k >= 1; k--) {
                int t = tauAt(k, K), tp = tauAt(k - 1, K);
                ddimStep(s, x, predictEps(net, x, (float)t, -1), t, tp, eta, 1.25f, r);
            }
            return x;
        }

        // 同一步换个坐标看：x̄ = x/√ᾱ、σ̄ = √(1−ᾱ)/√ᾱ，概率流 ODE 变成 dx̄/dσ̄ = ε(x, t)，η = 0 的 DDIM 正是它的欧拉法
        void ddimEulerForm(const Schedule& s, Tensor& x, const Tensor& eps, int t, int tp) {
            float at = s.abar[t], ap = s.abar[tp];
            float sbt = std::sqrt((1 - at) / at), sbp = std::sqrt((1 - ap) / ap);
            for (int i = 0; i < x.size(); i++) {
                float xb = x.v[i] / std::sqrt(at) + (sbp - sbt) * eps.v[i];   // x̄_{t'} = x̄_t + (σ̄_{t'} − σ̄_t)·ε̂
                x.v[i] = std::sqrt(ap) * xb;
            }
        }`,
    cfg: `
        // 训练：同一个网络，以概率 p_uncond 把类别换成空条件 ∅ → 一次训练同时学会 ε(x, c) 和 ε(x, ∅)（本页 p_uncond = 0.2）
        float trainStepCFG(Denoiser& net, AdamW& opt, const Tensor& data, const std::vector<int>& arm, const Schedule& s, int B, float lr, float pUncond, Rng& r) {
            Tensor x = zeros(B, 2), eps = zeros(B, 2);
            std::vector<float> t = floats(B);
            std::vector<int> c = ints(B);
            for (int b = 0; b < B; b++) {
                int j = randint(r, data.rows);
                c[b] = uniform(r) < pUncond ? -1 : arm[j];               // 条件丢弃（condition dropout）
                int ti = 1 + randint(r, T_STEPS);
                float a = std::sqrt(s.abar[ti]), sg = std::sqrt(1 - s.abar[ti]);
                for (int d = 0; d < 2; d++) { eps.at(b, d) = randn(r); x.at(b, d) = a * data.at(j, d) + sg * eps.at(b, d); }
                t[b] = (float)ti;
            }
            std::vector<Var> ps = parameters(net);
            zeroGrad(ps);
            Var loss = mse(denoise(net, x, condRows(net, t, c)), constant(eps));
            backward(loss);
            clipGradNorm(ps, 1.0f);
            adamwStep(opt, lr);
            return loss->val.v[0];
        }

        // 采样：ε̃ = ε(x, ∅) + s·(ε(x, c) − ε(x, ∅))。s = 0 无条件，s = 1 普通条件模型，s > 1 引导（每步多算一次前向）
        Tensor cfgEps(const Denoiser& net, const Tensor& x, float t, int cls, float guide) {
            Tensor ec = predictEps(net, x, t, cls), eu = predictEps(net, x, t, -1);
            for (int i = 0; i < ec.size(); i++) ec.v[i] = eu.v[i] + guide * (ec.v[i] - eu.v[i]);
            return ec;
        }

        // 带引导的 DDIM（η = 0）。clip = x̂₀ 的截断范围（二维数据 1.25；标准化的潜变量 4）
        Tensor sampleCFG(const Denoiser& net, const Schedule& s, Tensor x, int cls, float guide, int K, float clip) {
            Rng r = makeRng(1);
            for (int k = K; k >= 1; k--) {
                int t = tauAt(k, K), tp = tauAt(k - 1, K);
                ddimStep(s, x, cfgEps(net, x, (float)t, cls, guide), t, tp, 0.f, clip, r);
            }
            return x;
        }`,
    flow: `
        // 流匹配 / rectified flow（本页的时间方向：t = 0 数据、t = 1 噪声，与 SD3 相同）：
        //   x_t = (1 − t)·x₀ + t·ε，回归目标 v = dx_t/dt = ε − x₀，t ~ U(0, 1)
        // pairZ.rows == 0：每步重新抽噪声（1-RF，即普通流匹配）；否则用 reflow 配好的 (x₀, z) 对（2-RF）
        float trainStepFM(Denoiser& net, AdamW& opt, const Tensor& x0s, const Tensor& pairZ, int B, float lr, Rng& r) {
            Tensor x = zeros(B, 2), v = zeros(B, 2);
            std::vector<float> t = floats(B);
            for (int b = 0; b < B; b++) {
                int j = randint(r, x0s.rows);
                float tb = (float)uniform(r);
                for (int d = 0; d < 2; d++) {
                    float z = pairZ.rows ? pairZ.at(j, d) : randn(r);
                    x.at(b, d) = (1 - tb) * x0s.at(j, d) + tb * z;
                    v.at(b, d) = z - x0s.at(j, d);
                }
                t[b] = 1000 * tb;                                         // 同一个时间编码：输入 1000·t
            }
            std::vector<Var> ps = parameters(net);
            zeroGrad(ps);
            Var loss = mse(denoise(net, x, condRows(net, t, ints(B, -1))), constant(v));
            backward(loss);
            clipGradNorm(ps, 1.0f);
            adamwStep(opt, lr);
            return loss->val.v[0];
        }

        // 欧拉法从 t = 1 积到 t = 0：x ← x − (1/K)·v̂(x, t)。K = 1 时一步到位：x₀ = z − v̂(z, 1)
        Tensor sampleFlow(const Denoiser& net, Tensor x, int K) {
            for (int k = K; k >= 1; k--) {
                Tensor v = predictEps(net, x, 1000.f * k / K, -1);
                for (int i = 0; i < x.size(); i++) x.v[i] -= v.v[i] / K;
            }
            return x;
        }

        // reflow（Liu et al. 2022）：用 1-RF 把噪声 z 积分成 x₀ = ODE(z)，得到「配好对」的数据，再在这些对上训练 2-RF
        void makeReflowPairs(const Denoiser& net, int n, int K, Rng& r, Tensor& z, Tensor& x0) {
            z = randn(n, 2, 1.f, r);
            x0 = sampleFlow(net, z, K);                                  // 本页：8192 对、欧拉 100 步
        }

        // 轨迹的弯曲度：路径长 / 起点到终点的直线距离（1 = 笔直）。traj[k] = 第 k 步所有粒子的位置
        struct Trajectory { std::vector<Tensor> steps; };
        double pathRatio(const Trajectory& tr) {
            int n = tr.steps[0].rows, K = (int)tr.steps.size() - 1;
            double sum = 0;
            for (int i = 0; i < n; i++) {
                double len = 0;
                for (int k = 0; k < K; k++) len += std::hypot(tr.steps[k + 1].at(i, 0) - tr.steps[k].at(i, 0), tr.steps[k + 1].at(i, 1) - tr.steps[k].at(i, 1));
                sum += len / std::max(1e-9, (double)std::hypot(tr.steps[K].at(i, 0) - tr.steps[0].at(i, 0), tr.steps[K].at(i, 1) - tr.steps[0].at(i, 1)));
            }
            return sum / n;
        }`,
    latent: `
        // ── 潜空间扩散（Rombach et al. 2022 的思路，缩小版）：先把 16×16 的数字压成 8 维潜变量，在潜空间里做扩散，最后解码 ──
        struct AutoEncoder { Linear e1, e2, d1, d2; };                     // 256 → 64 → 8 → 64 → 256（离线训练 4000 步，tools/p11_train.js）

        Var encode(const AutoEncoder& ae, const Var& x) { return forward(ae.e2, silu(forward(ae.e1, x))); }
        Var decode(const AutoEncoder& ae, const Var& z) { return sigmoid(forward(ae.d2, silu(forward(ae.d1, z)))); }

        // 训练潜空间去噪器的数据：每维按训练集的均值 μ、标准差 sd 标准化（Stable Diffusion 用一个全局 scale factor 做同样的事）
        Tensor latentDataset(const AutoEncoder& ae, const Tensor& images, std::vector<float>& mu, std::vector<float>& sd) {
            NoGrad ng;
            Tensor z = encode(ae, constant(images))->val;
            int n = z.rows, d = z.cols;
            mu = floats(d); sd = floats(d);
            for (int i = 0; i < n; i++) for (int k = 0; k < d; k++) mu[k] += z.at(i, k) / n;
            for (int i = 0; i < n; i++) for (int k = 0; k < d; k++) sd[k] += (z.at(i, k) - mu[k]) * (z.at(i, k) - mu[k]) / n;
            for (int k = 0; k < d; k++) sd[k] = std::sqrt(sd[k]);
            for (int i = 0; i < n; i++) for (int k = 0; k < d; k++) z.at(i, k) = (z.at(i, k) - mu[k]) / sd[k];
            return z;                                                  // 之后照常训练：makeDenoiser(8, 64, 3, 10, false, r) + 条件丢弃
        }

        // 生成：8 维潜空间里 50 步 DDIM + CFG，反标准化，再用解码器变回图像。返回 [n × 256]，每行一张 16×16 的图
        Tensor generateDigits(const Denoiser& ldm, const AutoEncoder& ae, const std::vector<float>& mu, const std::vector<float>& sd, const Schedule& s, int digit, float guide, int n, Rng& r) {
            Tensor z = sampleCFG(ldm, s, randn(n, 8, 1.f, r), digit, guide, 50, 4.f);
            for (int i = 0; i < n; i++) for (int k = 0; k < 8; k++) z.at(i, k) = z.at(i, k) * sd[k] + mu[k];
            NoGrad ng;
            return decode(ae, constant(z))->val;
        }`,
    prod: `
        // v 预测（Salimans & Ho 2022）：v = √ᾱ·ε − √(1 − ᾱ)·x₀。三种参数化可以互相换算，而且在 ᾱ → 0（纯噪声端）也不会除以 0：
        //   x̂₀ = √ᾱ·x_t − √(1 − ᾱ)·v̂，ε̂ = √(1 − ᾱ)·x_t + √ᾱ·v̂
        void fromV(const Tensor& x, const Tensor& v, float abar, Tensor& x0, Tensor& eps) {
            float a = std::sqrt(abar), sg = std::sqrt(1 - abar);
            x0 = zeros(x.rows, x.cols); eps = zeros(x.rows, x.cols);
            for (int i = 0; i < x.size(); i++) { x0.v[i] = a * x.v[i] - sg * v.v[i]; eps.v[i] = sg * x.v[i] + a * v.v[i]; }
        }

        // Stable Diffusion 的「scaled linear」日程：β 在 √β 上线性，0.00085 → 0.012
        Schedule makeScaledLinear() {
            Schedule s;
            s.beta = floats(T_STEPS + 1);
            s.abar = floats(T_STEPS + 1, 1.f);
            double ab = 1, b0 = std::sqrt(0.00085), b1 = std::sqrt(0.012);
            for (int t = 1; t <= T_STEPS; t++) {
                double sb = b0 + (b1 - b0) * (t - 1) / (T_STEPS - 1);
                ab *= 1 - sb * sb;
                s.beta[t] = (float)(sb * sb);
                s.abar[t] = (float)ab;
            }
            return s;
        }

        // rectified flow 的 SNR：x_t = (1 − t)·x₀ + t·ε → SNR = (1 − t)²/t²（t = 1 时正好为 0）
        double logSNRFlow(double t) { return 2 * std::log((1 - t) / t); }`,
};

const P11S = (() => {   // 舞台（stage）之间共用的小工具
    const COS = P11.SCHED.cosine;                  // 离线模型都用 cosine 日程训练
    const memo = (S, name, key, fn) => { const c = S[name]; if (c && c.key === key) return c; const v = fn(); v.key = key; S[name] = v; return v; };
    const TV = (S) => Math.max(1, S.tv);
    const decodeOne = (S, z) => P11.decodeLatents(S.M.lat, z, z.length / P11.AE_Z);
    return { COS, memo, TV, decodeOne };
})();

