                    const P = new Float32Array(2 * n); for (let j = 0; j < G; j++) for (let k = 0; k < G; k++) { P[2 * (j * G + k)] = -v + (k + 0.5) / G * 2 * v; P[2 * (j * G + k) + 1] = v - (j + 0.5) / G * 2 * v; }
                    const eN = P11.epsNet(S.M.vp)(P, n, i, new Float32Array(2 * n)), eX = P11.epsExact(sch)(P, n, i, new Float32Array(2 * n));
